// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import SemanticExample from "./variants/semantic";

const SemanticSource = "import { semanticColors, tagColors, softColors } from "../helpers";

const Example = () => (
  <div className="grid max-w-2xl gap-8">
    <section className="grid gap-3">
      <h2 className="text-sm font-medium">Semantic colors</h2>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {semanticColors.map(([name, colors]) => (
          <div key={name} className={`rounded-lg p-3 text-sm font-medium ${colors}`}>
            {name}
          </div>
        ))}
      </div>
    </section>
    <section className="grid gap-3">
      <h2 className="text-sm font-medium">Soft semantic colors</h2>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {softColors.map(([name, colors]) => (
          <div key={name} className={`rounded-lg p-3 text-sm font-medium ${colors}`}>
            {name}
          </div>
        ))}
      </div>
    </section>
    <section className="grid gap-3">
      <h2 className="text-sm font-medium">Categorical tag colors</h2>
      <div className="flex flex-wrap gap-2">
        {tagColors.map(([name, colors]) => (
          <span key={name} className={`rounded-full px-2.5 py-1 text-xs font-medium ${colors}`}>
            {name}
          </span>
        ))}
      </div>
    </section>
  </div>
);

export default Example;
";

const meta = {
  parameters: {
    docs: { description: { component: "Semantic tokens cover backgrounds, text, borders, and feedback. Use semantic colors such as `background`, `foreground`, `primary`, and `muted` so your interface follows the shared theme. Feedback colors provide matching foregrounds for success, warning, error, and information states.

The swatches below render the same theme tokens used by Erbium components. Compare their foregrounds and backgrounds when choosing a role for your interface.

Default filled actions use neutral `primary` colors. Use `link` for links, `selection` and `selection-foreground` for checked or selected controls, and `ring` for keyboard focus. Links, selection, and focus retain the Vitesse green independently of the default action fill. `accent` remains the neutral hover background.

Feedback colors keep separate solid and soft foreground pairs. Tag colors represent categories, and chart colors represent data series; keep those roles separate from action and status colors even when their values match. Surface tokens continue to describe elevation and interaction states." } },
    layout: "padded",
  },
} satisfies Meta;

export default { ...meta, title: "Foundations/Colors",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Semantic: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: SemanticSource },
    },
  },
  render: SemanticExample,
};

import { semanticColors, tagColors, softColors } from "../helpers";

const Example = () => (
  <div className="grid max-w-2xl gap-8">
    <section className="grid gap-3">
      <h2 className="text-sm font-medium">Semantic colors</h2>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {semanticColors.map(([name, colors]) => (
          <div key={name} className={`rounded-lg p-3 text-sm font-medium ${colors}`}>
            {name}
          </div>
        ))}
      </div>
    </section>
    <section className="grid gap-3">
      <h2 className="text-sm font-medium">Soft semantic colors</h2>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {softColors.map(([name, colors]) => (
          <div key={name} className={`rounded-lg p-3 text-sm font-medium ${colors}`}>
            {name}
          </div>
        ))}
      </div>
    </section>
    <section className="grid gap-3">
      <h2 className="text-sm font-medium">Categorical tag colors</h2>
      <div className="flex flex-wrap gap-2">
        {tagColors.map(([name, colors]) => (
          <span key={name} className={`rounded-full px-2.5 py-1 text-xs font-medium ${colors}`}>
            {name}
          </span>
        ))}
      </div>
    </section>
  </div>
);

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout"
    >
      {children}
    </div>
  );
}
